<script setup>import{onMounted,ref}from'vue';import{request}from'../api';const org='DEMO-AP',data=ref({invoices:[],openExceptions:0,unpaidAmount:0}),busy=ref(false),error=ref('');async function load(){try{data.value=await request('/api/ap/dashboard?organizationCode='+org)}catch(e){error.value=e.message}}async function scenario(){busy.value=true;error.value='';try{const x=Date.now(),poNo='PO-'+x,po=await request('/api/ap/purchase-order-lines',{method:'POST',body:JSON.stringify({organizationCode:org,poNo,lineNo:1,vendorCode:'VENDOR-001',itemCode:'SERVER',orderedQty:10,unitPrice:8000})});await request(`/api/ap/purchase-order-lines/${po.id}/receipts`,{method:'POST',body:JSON.stringify({receiptNo:'GR-'+x,quantity:10,receiptDate:new Date().toISOString().slice(0,10),receiver:'仓储主管'})});const invoice=await request('/api/ap/invoices',{method:'POST',body:JSON.stringify({organizationCode:org,vendorCode:'VENDOR-001',invoiceNo:'INV-'+x,currency:'CNY',totalAmount:80000,taxAmount:0,invoiceDate:new Date().toISOString().slice(0,10),dueDate:'2026-09-30',lines:[{lineNo:1,poNo,poLineNo:1,itemCode:'SERVER',quantity:10,unitPrice:8000}]})});await request(`/api/ap/invoices/${invoice.id}/match`,{method:'POST',body:JSON.stringify({tolerancePercent:.5})});await request(`/api/admin/ap/invoices/${invoice.id}/approve`,{method:'POST'});await load()}catch(e){error.value=e.message}finally{busy.value=false}}onMounted(load)</script>
<template><section class="dw-head"><div><span>ACCOUNTS PAYABLE</span><h3>发票与三单匹配中心</h3><p>以订单行、收货数量和发票行执行可审计的行级匹配。</p></div><button @click="scenario" :disabled="busy">{{busy?'匹配处理中…':'创建三单匹配场景'}}</button></section><p v-if="error" class="err">{{error}}（批准需要管理员账号）</p><section class="metrics"><article><span>发票数量</span><b>{{data.invoices.length}}</b></article><article><span>待付金额</span><b>¥{{Number(data.unpaidAmount||0).toLocaleString()}}</b></article><article><span>开放异常</span><b>{{data.openExceptions}}</b></article><article><span>匹配通过</span><b>{{data.invoices.filter(i=>['MATCHED','APPROVED','SCHEDULED','PAID'].includes(i.status)).length}}</b></article></section><section class="panel"><h4>供应商发票</h4><table><tr><th>发票/供应商</th><th>金额</th><th>开票日</th><th>到期日</th><th>匹配状态</th></tr><tr v-for="i in data.invoices" :key="i.id"><td><b>{{i.invoiceNo}}</b><small>{{i.vendorCode}}</small></td><td>{{i.currency}} {{Number(i.totalAmount).toLocaleString()}}</td><td>{{i.invoiceDate}}</td><td>{{i.dueDate}}</td><td><i>{{i.status}}</i></td></tr></table></section></template>
<style scoped>.dw-head{display:flex;justify-content:space-between;align-items:end;background:#3b352b;color:#fff;padding:26px 30px;border-radius:14px}.dw-head span{font-size:11px;letter-spacing:.16em;color:#d6c7a9}.dw-head h3{font-size:25px;margin:7px 0}.dw-head p{margin:0;color:#ded7ca}.dw-head button{background:#dcae58;border:0;border-radius:8px;padding:12px 18px;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:18px 0}.metrics article,.panel{background:#fff;border:1px solid #e4e0d9;border-radius:12px;padding:20px}.metrics b{display:block;font-size:28px;margin-top:8px}.metrics span{color:#776f64}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #eeeae4}td small{display:block;color:#847d73}td i{font-style:normal;color:#246b55}.err{color:#a43b35}@media(max-width:900px){.metrics{grid-template-columns:1fr 1fr}}</style>
